$sets['Horror Surrealism Style Melting and Distortion'] = @('Melting candle face','Stretched figure in a doorway','Body dissolving into smoke','Hand melting into a puddle of eyes','Twisted spiral of faces','Skull melting over a clock','Upside-down figure on the ceiling','Shadow that does not match','Face reflected wrong in water','Figure folding into itself')
