$sets['Horror Surrealism Style Large Pieces'] = @('Nightmare forest back piece','Creature in fog sleeve','Haunted house chest piece','Eyes and moths thigh piece','Long-limbed figure forearm piece','Teeth and roses spine piece','Masked figures half sleeve','Doorway in the woods calf piece','Melting faces shoulder piece','Forest of hands leg sleeve')
$fix = { param($n) if ($tk.ContainsKey((& $slug $n))) { "$n in Horror Surrealism Style" } else { $n } }
$all = @()
foreach ($k in $sets.Keys) {
  $have = @($tt.specific.$k)
  if ($have.Count -ne $sets[$k].Count) {
    $names = @($sets[$k] | % { & $fix $_ })
    "  REPAIRED " + $k + ": had " + $have.Count + " of " + $names.Count
    RUN ("LEAVES " + $k + " :: " + ($names -join ", ")) | Out-Null
    foreach ($leaf in $names) { $base = $leaf -replace ' in Horror Surrealism Style$',''; RUN ("SETKV build:" + (& $slug $leaf) + " " + $b[$base]) | Out-Null }
    $have = $names
  }
  $all += @($have | ? { ($_ -replace ' in Horror Surrealism Style$','') -ne 'Moth with eyes on its wings' })
}
"== drawing " + $all.Count + " Horror Surrealism split cards, 5 at a time =="
for ($i = 0; $i -lt $all.Count; $i += 5) { RUN ("REDO " + (($all[$i..([Math]::Min($i+4,$all.Count-1))]) -join ", ")) }
RUN "WALK Horror Surrealism"
RUN "SHEET Horror Surrealism"
}
